/** How long `app/navigate`'s step waits for the tab that asked: a tab that is open answers in milliseconds. */
export const NAVIGATE_WITHIN = "5 seconds";
/** The longest `to` the flow takes. */
export const MAX_TO_LENGTH = 2_048;
/** Why `app/navigate` refused a target: another scheme (`javascript:`, `data:`, ...), another origin, or no URL. */
export const REFUSALS = ["scheme", "origin", "invalid"];
/**
 * How a navigation ended: the tab moved (`navigated`), the target was refused (`refused`), no tab answered because the
 * one that asked is gone (`gone`), or the tab answered without moving (`failed`).
 */
export const OUTCOMES = ["navigated", "refused", "gone", "failed"];
/**
 * The `BroadcastChannel` the engine worker asks the tabs of engine `name` on. A `BroadcastChannel` reaches only its own
 * origin's tabs and workers.
 *
 * @throws {never}
 */
export const navigationChannel = (name) => `${name}/navigate`;
